describe('Permissions Error Handling', () => {
    beforeEach(() => {
        cy.visit('/login');
        cy.login('user1', 'password1'); // Assuming a custom command for login
        cy.visit('/content/123'); // Visiting content owned by user1
    });

    it('should allow the owner to edit their own content', () => {
        cy.get('button.edit').click();
        cy.get('input[name="title"]').clear().type('Updated Title');
        cy.get('button.save').click();
        cy.get('.notification').should('contain', 'Content updated successfully');
    });

    it('should show a permissions error when trying to edit another user\'s content', () => {
        cy.visit('/content/456'); // Visiting content owned by user2
        cy.get('button.edit').click();
        cy.get('.error-message').should('contain', 'You do not have permission to edit this content');
    });
});
